import React, { useState } from "react";
import InputField from "../components/InputField";

const PersonFilter = ({ handleFilter }) => {
    const [filter, setFilter] = useState({ identificationNumber: "" });

    const handleChange = (e) => {
        setFilter((prev) => ({ ...prev, [e.target.name]: e.target.value }));
    };    

    const handleSubmit = (e) => {
        e.preventDefault();
        handleFilter((prev) => ({ ...prev, ...filter }));
    };

    return (
        <form onSubmit={handleSubmit}>   
            <div className="row">
                <div className="col-9">
                    <InputField
                    type="text"
                    name="identificationNumber"
                    handleChange={handleChange}
                    label="Identifikační číslo"
                    prompt="-"
                    value={filter.identificationNumber}
                    />
                </div>
                <div className="col-3">
                    <InputField
                        type="number"
                        min="1"
                        name="limit"
                        handleChange={handleChange}
                        label="Limit počtu osob"
                        value={filter.limit || "10"}
                    />
                </div>

            </div>
            <input type="submit" className="btn btn-secondary mt-2" value="Filtrovat" />
        </form>
    );
};

export default PersonFilter;
